import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"The simulation replays identically at any host speed","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"The simulation replays identically at any host speed"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/_media/0006-replay-determinism-contract"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/_media/0006-replay-determinism-contract"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/tools/docs/site/api/_media/0006-replay-determinism-contract.md"}},"headers":[],"relativePath":"api/_media/0006-replay-determinism-contract.md","filePath":"api/_media/0006-replay-determinism-contract.md","lastUpdated":0}`),a={name:`api/_media/0006-replay-determinism-contract.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<h1 id="the-simulation-replays-identically-at-any-host-speed" tabindex="-1">The simulation replays identically at any host speed <a class="header-anchor" href="#the-simulation-replays-identically-at-any-host-speed" aria-label="Permalink to “The simulation replays identically at any host speed”">​</a></h1><p>Status: accepted</p><p>Given an initial-state manifest, the random state and an ordered inbound packet trace, a replay produces the same per-tick replay digest series and the same outbound packet digests on every run, however fast the host is. The contract does not extend across code versions, Node or V8 versions, or platforms, because floating-point and library behavior can differ between them. The replay digest covers authoritative state only. Spatial indexes, tracking sets and dirty flags are derived from that state, so they stay out of it, and a derived structure can change without changing the digest.</p><p>The server&#39;s first job is to behave like the Minecraft players know while following Mojang&#39;s releases through data. A replay is the one check that catches a behavior change no unit test names, and it only works when two runs of the same input agree. The replay suites (<code>SessionReplay.test.ts</code> and the entity AI replay) are therefore the acceptance check for any change to the simulation core.</p><p>The outbound packet digest covers the packets replication produces from a tick&#39;s change log (<a href="./0016-replication-reads-the-change-log.html">ADR 0016</a>), and each packet counts toward the tick whose log produced it, not the tick in which the transport framed it. Chunk streaming and the replies of read-lane handlers (<a href="./0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>) stay out of the digest. They answer one connection from state the replay digest already covers, and they leave when the request arrives, which no tick decides.</p><p>Two runs can disagree today. Block updates and scheduled ticks stop on <code>performance.now()</code> budgets (20 ms in <code>World.ts</code>, 25 ms in <code>WorldSystems.ts</code>), so a slow host defers work that a fast host runs in the same tick. Wall-clock time must not decide what the simulation does. Count budgets are allowed, because the same input produces the same count on every host.</p>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};